WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_111'), '#include <limits.h>
#include <stdint.h>

int big = INT_MAX;
unsigned int u = 0;
uint8_t a = 200, b = 100;

On x86-64 Linux with gcc 15 (-std=c23), which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'Unsigned arithmetic is defined to wrap modulo 2^N, so u - 1 is UINT_MAX (4294967295 for a 32-bit unsigned int) on every conforming compiler. big + 1 is signed overflow: undefined behaviour. One build may print INT_MIN, another may do something else, and UBSan reports it; the standard guarantees nothing. a + b is computed after integer promotion: both uint8_t operands become int first, so the result is an int with the value 300 (it only becomes 44 if you store it back into a uint8_t). Integer division truncates toward zero, so -7 / 2 is -3, not -4. sizeof(long) is implementation-defined: 8 on 64-bit Linux (LP64), but 4 on 64-bit Windows.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('u - 1 is UINT_MAX (4294967295), and the C standard guarantees that result', true),
        ('big + 1 is INT_MIN (-2147483648), and the C standard guarantees that result', false),
        ('a + b has type int and the value 300', true),
        ('-7 / 2 is -4', false),
        ('sizeof(long) is 8 on every C compiler', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_111'), '#include <stdio.h>

int main(void)
{
    unsigned int stock = 2;
    int sold = 3;
    if (stock - sold < 0)
        printf("oversold\n");
    else
        printf("stock=%u\n", stock - sold);
    return 0;
}

What does this program print (gcc 15, x86-64 Linux)?', 'single_choice'::question_type, 'stock - sold mixes unsigned int and int, so sold is converted to unsigned int and the subtraction is done in unsigned arithmetic: 2 - 3 wraps to 4294967295. That is defined behaviour, not UB. An unsigned value is never less than 0, so the if is always false (gcc -Wextra even warns that the comparison is always false), and the else branch prints the wrapped value. To detect "not enough stock", compare before subtracting (if (sold > stock)) or use ckd_sub, which returns true when the exact result does not fit.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('oversold', false),
        ('stock=-1', false),
        ('stock=4294967295', true),
        ('Nothing predictable: it is undefined behaviour', false)
    ) AS o(option_text, is_correct);

