INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cf_211', (SELECT id FROM catalog.course WHERE public_id = 'c-foundations-memory'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'c-foundations-memory') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cf-2-1' AND is_deleted = false LIMIT 1), 'pointer-arithmetic-quiz', 'Where does the pointer point?', 'Predict what pointer arithmetic, indexing and the one-past-the-end pointer really do before you write an in-place function.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_211'), '#include <stdio.h>

int main(void) {
    int a[5] = {10, 20, 30, 40, 50};
    int *p = a + 1;
    printf("%d %d %td\n", *(p + 2), p[-1], &a[4] - p);
    return 0;
}

What does it print?', 'single_choice'::question_type, 'p = a + 1 points at a[1] (20). *(p + 2) is the element two ints further: a[3] = 40. p[-1] means *(p - 1), which is a[0] = 10; a negative index is fine as long as the result stays inside the array. &a[4] - p subtracts two pointers into the same array and gives the distance in ELEMENTS, not bytes: 4 - 1 = 3, of type ptrdiff_t, printed with %td. Output: 40 10 3.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_211') AND order_index = 1)
    RETURNING id
)
