SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('end - a is 4, and its type is ptrdiff_t.', true),
        ('Reading *end is fine; it just gives an unspecified number.', false),
        ('Inside f, sizeof a is 8, not 16.', true),
        ('With const int *q = a; the statement q++; is a compile error.', false),
        ('Computing a + 5 (without reading it) is valid, like a + 4.', false)
    ) AS o(option_text, is_correct);

