-- challenge chal_quiz_cf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_cf_311', (SELECT id FROM catalog.course WHERE public_id = 'c-foundations-memory'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'c-foundations-memory') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-cf-3-1' AND is_deleted = false LIMIT 1), 'heap-lifetimes-quiz', 'Who owns this memory?', 'Read each snippet the way C runs it: which pointers share one buffer, which functions leak or leave a dangling pointer, and what free really does.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_311'), 'What does this print?

char buf[16];
char *names[3];
const char *scans[3] = {"TEA-500", "MUG-01", "CARD-TET"};
for (int i = 0; i < 3; i++) {
    snprintf(buf, sizeof buf, "%s", scans[i]);
    names[i] = buf;
}
printf("%s %s %s\n", names[0], names[1], names[2]);', 'single_choice'::question_type, 'names[i] = buf stores the ADDRESS of the one array buf, not its characters. All three entries hold the same address, and printf reads the array as it is at the end of the loop, so it prints the last name three times. Nothing here is undefined: buf is still alive. To keep three names you need three copies, for example names[i] = strdup(buf) (and a free for each later).', 1, 4
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('TEA-500 MUG-01 CARD-TET', false),
        ('CARD-TET CARD-TET CARD-TET', true),
        ('TEA-500 TEA-500 TEA-500', false),
        ('Undefined behaviour: buf is reused', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_311'), 'Which of these are free of memory bugs (no leak, no dangling pointer, no use-after-free)? Every list[i] holds a string from malloc/strdup that the list owns. (Select all that apply.)

/* A */
char *copy_sku(const char *s) {
    char *p = malloc(strlen(s) + 1);
    if (p == NULL)
        return NULL;
    memcpy(p, s, strlen(s) + 1);
    return p;
}

/* B */
char *scanner_label(void) {
    char buf[32];
    snprintf(buf, sizeof buf, "SCN-%02d", 7);
    return buf;
}

/* C */
bool replace_name(char *list[], size_t i, const char *s) {
    char *p = strdup(s);
    if (p == NULL)
        return false;
    free(list[i]);
    list[i] = p;
    return true;
}

/* D */
void replace_name(char *list[], size_t i, const char *s) {
    list[i] = strdup(s);
}', 'multiple_choice'::question_type, 'A allocates strlen(s) + 1 bytes (room for the ''\0''), checks for NULL and hands ownership to the caller: correct. B returns the address of a local array whose lifetime ends at the return: the pointer dangles (gcc warns -Wreturn-local-addr). C makes the new copy first, frees the old string it owns, then stores the new one: correct, and on failure the list is unchanged. D overwrites list[i] without freeing the old string, so that block can never be freed again: a leak (LeakSanitizer reports it), and it also ignores a NULL result.', 2, 3
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A - copy_sku', true),
        ('B - scanner_label', false),
        ('C - replace_name with strdup, free, store', true),
        ('D - replace_name that only assigns strdup(s)', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_311'), 'What happens here?

char *a = strdup("TEA-500");
char *b = a;
free(a);
a = NULL;
free(b);', 'single_choice'::question_type, 'a and b are two copies of the same address. free(a) releases the block; a = NULL changes only the variable a, not b, which still holds the old address. free(b) frees the same block a second time: a double free, which is undefined behaviour (ASan reports attempting double-free, gcc warns -Wuse-after-free). Setting a pointer to NULL protects only that one pointer, which is why a block should have exactly one owner that frees it.', 3, 3
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_311') AND order_index = 3)
    RETURNING id
)
