WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_421'), '#include <stdio.h>

typedef unsigned char BOOL;

int main(void)
{
    unsigned flags = 0x300;          /* bit 9 = COLD, bit 8 = FRAGILE */
    BOOL a = flags & 0x200;
    bool b = flags & 0x200;
    int  c = flags & 0x200;
    printf("%d %d %d\n", a, b, c);
    return 0;
}

Compiled with gcc -std=c23 on x86-64 Linux, what does it print?', 'single_choice'::question_type, 'flags & 0x200 is the unsigned value 512. Converting it to unsigned char keeps the value modulo 256, and 512 mod 256 is 0, so the COLD flag silently disappears from a. Converting any scalar to bool gives true (1) when the value is not zero, so b is 1. An int can hold 512, so c keeps the full value. gcc prints no warning for the BOOL line with -Wall -Wextra; only -Wconversion reports "may change value".', 1, 3
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_cf_421') AND order_index = 1)
    RETURNING id
)
